async function initDB(){db=await new Promise((res,rej)=>{const r=indexedDB.open('fangchi-personal-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('records');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});const saved=await new Promise((res,rej)=>{const r=db.transaction('records').objectStore('records').get('state');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});state=saved||seed();if(!saved)await save();}
async function save(){await new Promise((res,rej)=>{const t=db.transaction('records','readwrite');t.objectStore('records').put(state,'state');t.oncomplete=res;t.onerror=()=>rej(t.error);t.onabort=()=>rej(t.error||new Error('保存中断'));});}
async function commit(fn,message='已保存到当前浏览器'){const old=structuredClone(state);try{fn();await save();render();if(message)toast(message);return true;}catch(e){state=old;toast('保存失败：请检查浏览器存储空间，先导出备份。');return false;}}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function go(p){if(!pages[p])p='overview';page=p;query='';location.hash=p;$('#sidebar').classList.remove('open');render();window.scrollTo(0,0);}
function nav(){const pending=state.tasks.filter(t=>!t.done).length;$('#sidebar').innerHTML=`<div class="brand"><div class="brand-mark"><img src="./icon.svg?v=2" alt=""></div><div><strong>方驰车业</strong><small>好车的下一程，从这里开始</small></div></div><div class="nav-label">我的工作台</div>${['overview','inventory','requests','customers'].map(p=>navItem(p)).join('')}<div class="nav-label">门店经营</div>${['workshop','sales','finance','reports','tasks'].map(p=>navItem(p,p==='tasks'?pending:'')).join('')}<div class="side-bottom">${navItem('settings')}<button data-action="install">${ic('download')}安装到手机 / 电脑</button><div class="side-user"><span class="avatar">方</span><div>我的个人工作台<small>汽车主题版 · 本机保存</small></div></div></div>`;$('#mobile-nav').innerHTML=['overview','inventory','requests','customers','settings'].map(p=>`<button data-action="go" data-id="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${ic(pages[p][1])}${p==='settings'?'更多':pages[p][0].slice(0,2)}</button>`).join('');$('#topbar').innerHTML=`<button class="icon-btn menu-button" data-action="menu" aria-label="打开全部导航">${ic('menu')}</button><span class="mobile-title">方驰车业</span><div class="crumb">我的工作台 <b>/ &nbsp; ${pages[page][0]}</b></div><div class="top-right"><form class="searchbox" id="global-search">${ic('search')}<input aria-label="全局搜索车辆" name="query" placeholder="搜索车型 / 库存编号" value="${esc(query)}"></form><span class="private-pill">${ic('car')}我的车库</span><button class="icon-btn" data-action="go" data-id="tasks" aria-label="查看待办提醒">${ic('bell')}${pending?'<i class="notify-dot"></i>':''}</button><span class="avatar">方</span></div>`;}
function navItem(p,count=''){return `<button class="nav-button ${page===p?'active':''}" data-action="go" data-id="${p}" ${page===p?'aria-current="page"':''}>${ic(pages[p][1])}${pages[p][0]}${count!==''?`<span class="count">${count}</span>`:''}</button>`;}
