function render(){$('#main').dataset.page=page;nav();$('#main').innerHTML=({overview,inventory,requests,customers,workshop,sales,finance,reports,tasks,settings}[page])();}
function monthSeries(){return Array.from({length:6},(_,i)=>{const d=new Date(thisMonth()+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()-(5-i));const prefix=d.toISOString().slice(0,7),cs=sold().filter(c=>c.soldDate?.startsWith(prefix));return {label:(d.getUTCMonth()+1)+'月',count:cs.length,profit:sum(cs,gross),revenue:sum(cs,c=>c.sale)};});}
function barChart(){const series=monthSeries(),max=Math.max(1,...series.map(s=>s.profit));return `<div class="chart-wrap"><svg viewBox="0 0 650 175" role="img" aria-label="近六个月成交毛利柱状图，当前月为截至今天的累计值">${[0,1,2,3].map(i=>`<line x1="43" x2="642" y1="${139-i*40}" y2="${139-i*40}" stroke="#e9efea" stroke-dasharray="3 4"/><text x="0" y="${142-i*40}">${(max*i/3/10000).toFixed(0)}万</text>`).join('')}${series.map((s,i)=>{const h=Math.max(0,s.profit)/max*120;return `<rect x="${68+i*99}" y="${139-h}" width="43" height="${h}" rx="3" fill="${i===5?'#456fcb':'#bfd0eb'}"><title>${s.label}：${money(s.profit)}，${s.count}台</title></rect><text x="${89+i*99}" y="164" text-anchor="middle">${s.label}${i===5?'（本月）':''}</text>`;}).join('')}</svg></div>`;}
function garageHero(){const pending=state.tasks.filter(t=>!t.done&&t.date<=today()).length;return `<section class="garage-hero" aria-label="方驰车业经营车库"><img class="garage-hero-image" src="./assets/garage-hero-v2.png" alt="" fetchpriority="high"><div class="garage-hero-shade"></div><div class="garage-hero-copy"><div class="garage-welcome"><span class="garage-live"></span>方驰车业 · 我的经营车库</div><h1>好车有数，<br>生意有路。</h1><p>照顾好每一台车，也记住每一位客户。</p><div class="actions">${btn('拍照入库','add-car','primary','camera')}${btn('为客户找车','go','hero-secondary','search','requests')}</div></div><div class="garage-date">${new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'}).format(new Date())}</div><div class="garage-status">${ic('clock')} ${pending?`今天有 ${pending} 件待办，准备好出发。`:'今天的待办已完成，从容开启下一程。'}${linkBtn('去看看','go','tasks')}</div><span class="theme-caption">汽车主题视觉 · 非库存实拍</span></section><div class="garage-shortcuts"><button data-action="go" data-id="inventory"><span class="shortcut-icon">${ic('car')}</span><span><strong>我的车库</strong><small>${stock().length} 台在库车辆</small></span>${ic('arrow')}</button><button data-action="go" data-id="customers"><span class="shortcut-icon amber">${ic('users')}</span><span><strong>客户与机会</strong><small>${state.customers.filter(c=>!['已成交','暂缓'].includes(c.stage)).length} 位客户跟进中</small></span>${ic('arrow')}</button><button data-action="go" data-id="workshop"><span class="shortcut-icon slate">${ic('tool')}</span><span><strong>整备进度</strong><small>${state.jobs.filter(j=>j.status!=='已完成').length} 项工单待完成</small></span>${ic('arrow')}</button><button data-action="backup"><span class="shortcut-icon pale">${ic('download')}</span><span><strong>安心备份</strong><small>车辆照片与台账一起保存</small></span>${ic('arrow')}</button></div>`;}
function overview(){const ms=monthSold(),st=stock(),target=state.settings.target,pc=Math.min(100,Math.round(ms.length/target*100)),avg=ms.length?Math.round(sum(ms,c=>days(c.date,c.soldDate))/ms.length):0;const need=overdue();return garageHero()+demoStrip()+`<div class="kpi-grid">${kpi('在库车辆',st.length,'台',`<strong>${st.filter(c=>c.status==='在售').length} 台在售</strong>含预订、整备与待检测`,'car',true)}${kpi('库存成本占用',wan(sum(st,carCost)),'万元','收车价 + 已登记车辆费用','wallet')}${kpi('本月成交毛利',wan(sum(ms,gross)),'万元',`<strong>${ms.length} 台成交</strong>未扣门店运营费用`,'chart')}${kpi('本月平均成交周期',avg,'天',`${need.length} 台在库已满 45 天`,'clock')}</div><div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><div><h2>经营的节奏</h2><div class="panel-sub">近六个月成交毛利 · 本月为截至今日累计</div></div>${linkBtn('经营分析','go','reports')}</div><div class="panel-body"><div class="chart-summary"><div><small>本月成交额</small><strong>${wan(sum(ms,c=>c.sale))}<span class="mini muted"> 万元</span></strong></div><div><small>本月单车平均毛利</small><strong>${ms.length?money(sum(ms,gross)/ms.length):'¥0'}</strong></div><div class="filter-spacer"></div><div class="legend"><span><i></i>本月</span><span><i class="lighter"></i>历史</span></div></div>${barChart()}</div></section><section class="panel"><div class="panel-head"><div><h2>需要你看一眼的车</h2><div class="panel-sub">优先展示长库龄车辆，其次是最新入库</div></div>${linkBtn('全部库存','go','inventory')}</div><div style="height:16px"></div>${vehicleTable([...st].sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4),true)}<div class="table-footer"><span>库存毛利为挂牌价减已登记成本，不代表成交收益</span><span>${st.length} 台在库</span></div></section></div><div class="dashboard-right"><section class="panel goal-panel"><div class="goal-top"><h2>本月行程，稳步向前</h2>${ic('flag')}</div><div class="goal-dashboard"><svg class="goal-dial" viewBox="0 0 150 150" aria-hidden="true"><circle cx="75" cy="75" r="62" fill="none" stroke="#ffffff1c" stroke-width="8"/><circle cx="75" cy="75" r="62" fill="none" stroke="#f3b667" stroke-width="8" stroke-linecap="round" stroke-dasharray="${pc/100*389.56} 389.56" transform="rotate(-90 75 75)"/><path d="M75 16v5 M134 75h-5 M75 134v-5 M16 75h5" stroke="#ffffff3d" stroke-width="2"/></svg><div class="goal-number">${ms.length}<small>/ ${target} 台</small><span>本月已成交</span></div></div><div class="progress"><span style="width:${pc}%"></span></div><div class="goal-meta"><span>月度销售目标</span><span>已完成 ${pc}%</span></div><div class="goal-foot">${ic('car')} ${ms.length>=target?'本月目标已完成':`距离目标还差 ${target-ms.length} 台`} <button class="text-btn" style="margin-left:auto;font-size:10px" data-action="go" data-id="settings">调整</button></div></section><section class="panel"><div class="panel-head"><h2>经营提醒</h2>${badge(need.length+' 台需关注','amber')}</div><div class="priority-list"><div class="priority-item"><span class="priority-icon">${ic('clock')}</span><div><h3>${need.length} 台车库龄超过 45 天</h3><p>评估报价、补拍照片或同行流转</p></div>${linkBtn('查看','aged-stock')}</div><div class="priority-item"><span class="priority-icon green">${ic('wallet')}</span><div><h3>待收尾款 ${money(sum(sold(),receivable))}</h3><p>以成交价减已收车款计算</p></div>${linkBtn('查看','go','sales')}</div><div class="priority-item"><span class="priority-icon green">${ic('users')}</span><div><h3>${state.customers.filter(c=>c.next&&c.next<=today()&&!['已成交','暂缓'].includes(c.stage)).length} 位客户待跟进</h3><p>把意向变成下一次见面</p></div>${linkBtn('查看','go','customers')}</div></div></section><section class="panel tasks-panel"><div class="panel-head"><h2>今日待办</h2>${linkBtn('全部','go','tasks')}</div><div class="priority-list">${taskList(state.tasks.filter(t=>!t.done&&t.date<=today()).slice(0,4))||'<div class="notice">今天的待办已完成。</div>'}${linkBtn('添加一件事','add-task')}</div></section></div></div>`;}
function thumbnail(c){return c.photos?.length?`<img class="car-thumb" src="${esc(c.photos[0].data)}" alt="${esc(c.name)}封面">`:`<div class="car-thumb">${carArt(c.art,c.name)}</div>`;}
function vehicleTable(cs,compact=false){return cs.length?`<div class="table-wrap"><table><thead><tr><th>车辆信息</th><th>挂牌价</th>${compact?'':'<th>总成本</th><th>预期毛利</th>'}<th>库龄</th><th>状态</th><th>操作</th></tr></thead><tbody>${cs.map(c=>`<tr><td><div class="car-cell">${thumbnail(c)}<div><strong>${esc(c.name)}</strong><small>${c.year}年 · ${c.mileage}万公里 · ${esc(c.id.slice(0,8))}</small></div></div></td><td class="number">${wan(c.ask)} 万</td>${compact?'':`<td class="number">${wan(carCost(c))} 万</td><td class="number ${c.ask-carCost(c)<0?'negative':'positive'}">${money(c.ask-carCost(c))}</td>`}<td>${badge(days(c.date)+' 天',days(c.date)>=45?'amber':'gray')}</td><td>${badge(c.status,c.status==='整备中'||c.status==='待检测'?'amber':'')}</td><td>${linkBtn('档案','view-car',c.id)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><h3>还没有符合条件的车辆</h3><p>试试其他筛选，或先录入第一台车。</p>${btn('车辆入库','add-car','primary','camera')}</div>`;}
function inventory(){let cs=stock().filter(c=>(stockFilter==='全部'||stockFilter==='长库龄'?stockFilter!=='长库龄'||days(c.date)>=45:c.status===stockFilter)&&(!query||[c.name,c.trim,c.id,c.vin,c.color].join(' ').toLowerCase().includes(query.toLowerCase())));return heading('车辆库存','每一台车，都有自己的档案与下一程。',btn('导出库存','export-cars','','download')+btn('拍照 / 车辆入库','add-car','primary','camera'))+demoStrip()+`<div class="toolbar"><div class="tabs">${['全部','在售','整备中','待检测','已预订','长库龄'].map(t=>`<button data-action="stock-filter" data-id="${t}" class="${stockFilter===t?'active':''}">${t}</button>`).join('')}</div><div class="filter-spacer"></div><input class="filter" id="inventory-query" aria-label="筛选库存车辆" placeholder="搜索车型、VIN、编号" value="${esc(query)}"><button class="icon-btn" data-action="toggle-view" aria-label="切换列表或卡片视图">${ic(stockView==='list'?'grid':'file')}</button></div>${stockView==='list'?`<section class="panel">${vehicleTable(cs)}<div class="table-footer"><span>${cs.length} 台车辆 · 筛选结果成本 ${wan(sum(cs,carCost))} 万元</span><span>所有价格单位：人民币</span></div></section>`:`<div class="cards-grid">${cs.length?cs.map(vehicleCard).join(''):'<div class="empty">未找到符合条件的车辆</div>'}</div>`}`;}
function vehicleCard(c){return `<article class="vehicle-card"><div class="vehicle-image">${c.photos?.length?`<img src="${esc(c.photos[0].data)}" alt="${esc(c.name)}">`:carArt(c.art,c.name)}${badge(c.status)}<span class="photo-count">${c.photos?.length?c.photos.length+' 张照片':'示意图'}</span></div><div class="vehicle-body"><h3>${esc(c.name)}</h3><div class="vehicle-meta">${c.year}年 · ${c.mileage}万公里 · ${esc(c.city)}</div><div class="price-row"><div class="price">${wan(c.ask)}<small>万元</small></div>${badge(days(c.date)+' 天库龄',days(c.date)>=45?'amber':'gray')}</div><div class="card-foot"><span class="mini muted">总成本 ${wan(carCost(c))} 万</span>${btn('查看档案','view-car','small','',c.id)}</div></div></article>`;}
function regionMatches(region,city){if(!region||region==='全国')return true;const jiangsu=['江苏','南京','苏州','无锡','常州','镇江','扬州','泰州','南通','盐城','淮安','宿迁','徐州','连云港'];const nearby=[...jiangsu,'上海','浙江','杭州','宁波','温州','嘉兴','湖州','绍兴','金华','衢州','舟山','台州','丽水','安徽','合肥','芜湖','蚌埠','淮南','马鞍山','淮北','铜陵','安庆','黄山','滁州','阜阳','宿州','六安','亳州','池州','宣城','山东','济南','青岛','淄博','枣庄','东营','烟台','潍坊','济宁','泰安','威海','日照','临沂','德州','聊城','滨州','菏泽'];if(region==='江苏及周边')return nearby.some(n=>city.includes(n));if(region==='江苏')return jiangsu.some(n=>city.includes(n));return city.replace(/市$/,'').includes(region.replace(/市$/,''));}
function matches(r){return stock().filter(c=>{const tokens=r.model.toLowerCase().split(/\s+/).filter(Boolean);return tokens.every(t=>(c.name+' '+c.trim).toLowerCase().includes(t))&&(!r.budget||c.ask<=r.budget)&&(!r.minYear||c.year>=r.minYear)&&(!r.maxMileage||c.mileage<=r.maxMileage)&&(!r.color||r.color==='不限'||c.color===r.color)&&regionMatches(r.region,c.city);});}
function requests(){const r=state.requests.find(r=>r.id===selectedMatch)||state.requests[0];return heading('客户寻车','先记住需求，再把合适的车带到客户面前。',btn('收藏外部车源','add-candidate','','plus')+btn('新建寻车需求','add-request','primary','search'))+demoStrip()+`<div class="two-col"><div>${state.requests.length?state.requests.map(q=>`<article class="request-card"><div class="request-title"><div><h3>${esc(q.name)}</h3><span class="source-time">建立于 ${esc(q.created)} · ${state.demo?'演示需求':'个人记录'}</span></div>${badge(matches(q).length+' 台库存初步匹配')}</div><div class="request-tags">${[q.model,q.budget?wan(q.budget)+'万以内':'预算不限',q.minYear?q.minYear+'年及以后':'年份不限',q.maxMileage?q.maxMileage+'万公里以内':'里程不限',q.color||'颜色不限',q.region||'地区不限'].map(t=>badge(t,'gray')).join('')}</div><div class="request-note">车况要求：${esc(q.condition||'未填写')}<br>${esc(q.notes)}</div><div class="actions">${btn('查看库存匹配','match-request','small primary','car',q.id)}${btn('外部搜索入口','search-request','small','external',q.id)}${btn('编辑需求','edit-request','small','',q.id)}${btn('删除','delete-request','small danger','',q.id)}</div></article>`).join(''):`<div class="empty"><h3>把客户的一句话，变成一张寻车单</h3><p>记录车型、预算、年份、里程与车况要求。</p>${btn('新建寻车需求','add-request','primary','plus')}</div>`}${r?`<div class="line-title"><h2>「${esc(r.name)}」库存初筛</h2></div><div class="notice">${ic('info')}按车型、报价、年份、里程、颜色和地区匹配。“江苏及周边”按江苏、上海、浙江、安徽、山东的已知城市初筛，具体距离另行确认；事故、水泡、火烧及保养记录均须核实。</div><div class="cards-grid">${matches(r).length?matches(r).map(vehicleCard).join(''):'<div class="empty"><h3>当前库存没有合适的车</h3><p>可以打开外部搜索入口，或收藏找到的车源。</p></div>'}</div>`:''}<div class="line-title"><h2>收藏的外部车源</h2><span class="mini muted">${state.candidates.length} 条</span></div>${state.candidates.length?state.candidates.map(c=>`<div class="request-card"><div class="request-title"><h3>${esc(c.title)}</h3>${badge('待人工核实','amber')}</div><p class="mini muted">${esc(c.source)} · 记录于 ${esc(c.date)}${c.price?' · 报价 '+money(c.price):''}</p><p class="request-note">${esc(c.notes)}</p><div class="actions"><a class="btn small" href="${esc(safeURL(c.url))}" target="_blank" rel="noopener noreferrer">查看原始车源 ${ic('external')}</a>${btn('删除','delete-candidate','small danger','',c.id)}</div></div>`).join(''):'<div class="notice">找到感兴趣的车辆后，保存原始链接和关键条件，方便询价与复核。</div>'}</div><div><section class="panel"><div class="panel-head"><h2>车源连接</h2>${badge('第二版规划','gray')}</div><div class="panel-body"><div class="source-option"><div><h3>我的车辆库存</h3><p>按寻车条件实时初筛</p></div>${badge('已可用')}</div><div class="source-option"><div><h3>网上公开信息</h3><p>打开搜索引擎查询，再收藏链接</p></div>${badge('外部入口','gray')}</div><div class="source-option"><div><h3>授权车源接口</h3><p>后续接入真实在售数据与更新时间</p></div>${badge('未接入','amber')}</div><div class="source-option"><div><h3>方驰车业线上展厅</h3><p>后续对外展示车辆并接收咨询</p></div>${badge('未发布','gray')}</div></div></section><section class="panel"><div class="panel-head"><h2>寻车时，别漏了这些</h2></div><div class="panel-body"><div class="timeline">${[['确认具体车款','730Li 的年份、配置和排放标准都要写清楚。'],['区分报价和到手成本','车价之外，还可能有物流、过户、整备等费用。'],['车况必须有证据','卖家描述仅作线索，检测报告和实车复核另行确认。'],['保留原始来源','记录车源链接、报价日期和联系进度。']].map(([a,b])=>`<div class="timeline-item">${a}<small>${b}</small></div>`).join('')}</div></div></section></div></div>`;}
function customers(){const cs=state.customers.filter(c=>customerFilter==='全部'||c.stage===customerFilter);return heading('客户跟进','每一次认真回应，都是下一次成交的开始。',btn('新增客户','add-customer','primary','plus'))+demoStrip()+`<div class="toolbar"><div class="tabs">${['全部','高意向','已预约','洽谈中','初次沟通','已成交','暂缓'].map(t=>`<button class="${customerFilter===t?'active':''}" data-action="customer-filter" data-id="${t}">${t}</button>`).join('')}</div></div><div class="cards-grid">${cs.length?cs.map(c=>`<article class="customer-card"><div class="customer-top"><div class="customer-name"><span class="avatar">${esc(c.name[0])}</span><strong>${esc(c.name)}</strong></div>${badge(c.stage,c.stage==='高意向'?'amber':'')}</div><div class="customer-want">${esc(c.want)}</div><div class="customer-bottom"><span>${esc(c.source)} · ${esc(c.owner)}</span><span class="${c.next&&c.next<=today()?'negative':''}">${c.next?'下次 '+esc(c.next):'未安排跟进'}</span></div><div class="actions" style="margin-top:15px">${btn('跟进记录','view-customer','small primary','',c.id)}${btn('编辑','edit-customer','small','',c.id)}</div></article>`).join(''):'<div class="empty"><h3>还没有这类客户</h3><p>添加客户，记下意向和下一次联系时间。</p></div>'}</div>`;}
function workshop(){return heading('整备工单','进度、供应商和费用，每一项有着落。',btn('新建整备工单','add-job','primary','tool'))+demoStrip()+`<div class="notice">工单用于跟踪进度，工单预算不自动计入车辆成本。请在车辆档案中登记实际费用，避免重复计费。</div><div class="kanban">${['待安排','进行中','已完成'].map(s=>`<section class="kanban-column"><div class="kanban-heading"><span>${s}</span><span>${state.jobs.filter(j=>j.status===s).length}</span></div>${state.jobs.filter(j=>j.status===s).map(j=>{const c=state.cars.find(c=>c.id===j.carId);return `<article class="job"><h3>${esc(c?.name||'未关联车辆')}</h3><p>${esc(j.title)}</p><p>${esc(j.vendor)} · ${esc(j.date)}</p><div class="mini muted">${esc(j.note)}</div><div class="job-foot"><span class="mini">预算 ${money(j.amount)}</span>${s==='已完成'?badge('已完成'):btn(s==='待安排'?'开始整备':'完成工单','advance-job','small','',j.id)}</div><div style="margin-top:10px">${linkBtn('编辑工单','edit-job',j.id)}${c?linkBtn('车辆成本','view-car',c.id):''}</div></article>`;}).join('')||'<div class="mini muted" style="padding:15px 0">这里暂时没有工单</div>'}</section>`).join('')}</div>`;}
function sales(){const cs=[...sold()].sort((a,b)=>b.soldDate.localeCompare(a.soldDate));return heading('销售交付','成交只是开始，收好尾款，把车交好。',btn('登记成交','add-sale','primary','check'))+demoStrip()+`<section class="panel"><div class="stat-strip"><div><small>本月已成交</small><b>${monthSold().length} 台</b></div><div><small>全部待收尾款</small><b>${money(sum(cs,receivable))}</b></div><div><small>待交付车辆</small><b>${cs.filter(c=>c.delivery!=='已交付').length} 台</b></div></div>${cs.length?`<div class="table-wrap"><table><thead><tr><th>成交车辆</th><th>成交日期 / 客户</th><th>成交价 / 毛利</th><th>已收 / 待收</th><th>交付状态</th><th>操作</th></tr></thead><tbody>${cs.map(c=>`<tr><td><div class="car-cell">${thumbnail(c)}<div><strong>${esc(c.name)}</strong><small>${esc(c.trim)}</small></div></div></td><td>${esc(c.soldDate)}<div class="mini muted">${esc(c.buyer||'未填写')}</div></td><td>${money(c.sale)}<div class="mini ${gross(c)<0?'negative':'positive'}">毛利 ${money(gross(c))}</div></td><td>${money(c.received)}<div class="mini ${receivable(c)?'negative':'muted'}">待收 ${money(receivable(c))}</div></td><td>${badge(c.delivery||'待过户',c.delivery==='已交付'?'':'amber')}</td><td><div class="actions">${btn('收款 / 交付','delivery','small','',c.id)}${linkBtn('档案','view-car',c.id)}</div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>还没有成交记录</h3><p>从库存车辆中选择一台，登记成交价与收款情况。</p></div>'}</section>`;}
function finance(){const ls=[...state.ledger].sort((a,b)=>b.date.localeCompare(a.date)),month=ls.filter(l=>l.date.startsWith(thisMonth()));return heading('资金流水','每一笔进出，都留一条清楚的记录。',btn('导出流水','export-ledger','','download')+btn('记一笔收支','add-ledger','primary','plus'))+demoStrip()+`<div class="kpi-grid">${kpi('本月已记收入',wan(sum(month.filter(l=>l.type==='收入'),l=>l.amount)),'万元','按流水发生日期统计','wallet')}${kpi('本月已记支出',wan(sum(month.filter(l=>l.type==='支出'),l=>l.amount)),'万元','含收车、整备与门店费用','wallet')}${kpi('本月已记净流入',wan(sum(month,l=>l.type==='收入'?l.amount:-l.amount)),'万元','已记收入 − 已记支出；非账户余额','chart')}${kpi('售车待收款',wan(sum(sold(),receivable)),'万元','按成交档案计算','clock')}</div><div class="notice">车辆入库与成本登记不自动视为付款。登记成交与补收车款会同步新增收入流水；其他收支请手动登记。流水净额不是银行余额，门店运营支出不计入单车毛利。</div><section class="panel">${ls.length?`<div class="table-wrap"><table><thead><tr><th>日期</th><th>收支类型</th><th>金额</th><th>关联车辆</th><th>备注</th><th>操作</th></tr></thead><tbody>${ls.map(l=>`<tr><td>${esc(l.date)}</td><td>${badge(l.type,l.type==='支出'?'amber':'')} <span class="mini">${esc(l.category)}</span></td><td class="${l.type==='收入'?'positive':'negative'}">${l.type==='收入'?'+':'−'}${money(l.amount)}</td><td>${esc(state.cars.find(c=>c.id===l.carId)?.name||'—')}</td><td style="white-space:normal;min-width:200px;max-width:320px">${esc(l.note)}</td><td>${l.locked?'<span class="mini muted">关联成交</span>':btn('删除','delete-ledger','small danger','',l.id)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>从第一笔真实收支开始</h3><p>分别记录收车付款、整备、销售收款与门店运营。</p></div>'}</section>`;}
function reports(){const st=stock(),ms=monthSold(),ageGroups=[['0–15 天',st.filter(c=>days(c.date)<=15).length],['16–30 天',st.filter(c=>days(c.date)>15&&days(c.date)<=30).length],['31–45 天',st.filter(c=>days(c.date)>30&&days(c.date)<=45).length],['45 天以上',st.filter(c=>days(c.date)>45).length]];const brands=[...new Set(ms.map(c=>c.name.split(' ')[0]))].map(n=>({name:n,profit:sum(ms.filter(c=>c.name.split(' ')[0]===n),gross),count:ms.filter(c=>c.name.split(' ')[0]===n).length})).sort((a,b)=>b.profit-a.profit);return heading('经营分析','从台账里找答案，不凭感觉做决定。',btn('打印报表','print','','file'))+demoStrip()+`<div class="two-col"><section class="panel"><div class="panel-head"><h2>成交毛利走势</h2><span class="mini muted">最近六个月</span></div><div class="panel-body">${barChart()}<div class="notice" style="margin:20px 0 0">毛利 = 成交价 − 收车价 − 车辆费用。未扣门店房租、人工等运营成本；当月数据尚未结束。</div></div></section><section class="panel"><div class="panel-head"><h2>库存库龄结构</h2><span class="mini muted">当前库存 ${st.length} 台</span></div><div class="panel-body">${ageGroups.map(([n,v])=>`<div class="bar-row"><span>${n}</span><div class="bar-track"><div class="bar-fill" style="width:${st.length?v/st.length*100:0}%"></div></div><span>${v} 台</span></div>`).join('')}<p class="mini muted">已售车辆不计入库存库龄结构。</p></div></section></div><div class="two-col"><section class="panel"><div class="panel-head"><h2>本月品牌贡献</h2></div><div class="panel-body">${brands.length?brands.map(b=>`<div class="bar-row"><span>${esc(b.name)} · ${b.count}台</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(0,b.profit)/Math.max(1,...brands.map(b=>b.profit))*100}%"></div></div><span>${wan(b.profit)}万</span></div>`).join(''):'<div class="notice">本月暂无成交，登记后即可看到品牌贡献。</div>'}</div></section><section class="panel"><div class="panel-head"><h2>指标口径</h2></div><div class="panel-body"><div class="receipt-list">${[['库存成本占用','未售车辆的收车价 + 已记费用'],['成交周期','成交日期 − 入库日期'],['库存预期毛利','挂牌价 − 已记车辆总成本'],['销售待收款','成交价 − 累计已收款'],['金额单位','人民币；图表中万元另行标明']].map(([a,b])=>`<div><span>${a}</span><span class="mini muted">${b}</span></div>`).join('')}</div></div></section></div>`;}
function taskList(ts){return ts.map(t=>`<div class="priority-item"><button class="check ${t.done?'done':''}" data-action="toggle-task" data-id="${t.id}" aria-label="${t.done?'重新打开':'完成'}${esc(t.title)}">${t.done?'✓':''}</button><div class="task-content ${t.done?'done':''}"><h3>${esc(t.title)}</h3><p>${esc(t.type)}</p></div><span class="task-time">${t.date===today()?'今天':esc(t.date)}</span></div>`).join('');}
function tasks(){const cs=[...state.tasks].sort((a,b)=>Number(a.done)-Number(b.done)||a.date.localeCompare(b.date));return heading('待办提醒','把事情放在这里，让脑子轻松一点。',btn('新建待办','add-task','primary','plus'))+demoStrip()+`<section class="panel"><div class="panel-head"><h2>我的待办</h2><span class="mini muted">${cs.filter(t=>!t.done).length} 项未完成</span></div><div class="priority-list">${taskList(cs)||'<div class="empty">还没有待办，添加一件要记住的事。</div>'}</div></section>`;}
function settings(){return heading('设置与备份','你的台账，你来掌握。')+`<div class="two-col"><div><section class="panel"><div class="panel-head"><h2>我的经营目标</h2>${badge('个人版')}</div><div class="panel-body"><form id="settings-form"><div class="form-grid">${field('门店名称','storeName','text',state.settings.storeName,{readonly:true})}${field('每月销售目标（台）','target','number',state.settings.target,{min:1,max:10000,required:true,step:1})}</div><div class="form-actions">${btn('保存目标','submit-settings','primary')}</div></form></div></section><section class="panel"><div class="panel-head"><h2>数据与设备</h2></div><div class="panel-body"><div class="settings-block"><div><h3>完整备份</h3><p>导出车辆、照片、客户和全部记录。换设备时可导入恢复。</p></div>${btn('导出备份','backup','small','download')}</div><div class="settings-block"><div><h3>从备份恢复</h3><p>导入本系统导出的 JSON 文件，将替换当前浏览器台账。</p></div>${btn('导入备份','restore','small','upload')}</div><div class="settings-block"><div><h3>安装为应用</h3><p>支持的浏览器可添加至主屏幕或程序坞。当前版本仍在本机存储数据。</p></div>${btn('安装说明','install','small','download')}</div><div class="settings-block"><div><h3>${state.demo?'开始正式记录':'新建空白台账'}</h3><p>清空当前台账及照片，建立空白个人台账。请先导出备份。</p></div>${btn('建立空白台账','start-empty','small danger')}</div><div class="settings-block"><div><h3>体验演示</h3><p>载入虚构数据，探索各项功能。会替换当前本机台账。</p></div>${btn('载入演示','load-demo','small')}</div></div></section><section class="panel"><div class="panel-head"><h2>当前存储情况</h2></div><div class="panel-body"><div class="inline-stats"><div><strong>${state.cars.length}</strong><small>车辆档案</small></div><div><strong>${sum(state.cars,c=>c.photos.length)}</strong><small>车辆照片</small></div><div><strong>${(new Blob([JSON.stringify(state)]).size/1048576).toFixed(1)} MB</strong><small>台账数据量</small></div></div><div class="notice">当前为浏览器本机保存，无多人同步。清理网站数据、隐私浏览模式或更换设备可能使台账不可用。请定期备份；拍照会压缩为适合查看的图片，原图请自行保留。</div></div></section></div><div><section class="panel"><div class="panel-head"><h2>方驰车业的下一步</h2></div><div class="panel-body"><div class="roadmap"><h3>第一版 · 个人经营工作台</h3><p>车辆、照片、客户、寻车记录、成本与待办。现在可以使用。</p></div><div class="roadmap"><h3>第二版 · 车源与线上展厅</h3><p>接入授权车源，按客户需求汇总搜索结果。将选定车辆发布到店铺展厅，让客户咨询。</p></div><div class="roadmap"><h3>以后 · 协同与智能辅助</h3><p>跨设备同步、分工权限、拍照识别、消息提醒。按实际使用需求逐步增加。</p></div></div></section><section class="panel"><div class="panel-head"><h2>设计参考与边界</h2></div><div class="panel-body sources"><p>功能结构参考二手车经营软件公开介绍；台账中的经营数据全部来自当前浏览器记录。</p><a href="https://www.jiandaoyun.com/index/solutions-used-car" target="_blank" rel="noopener noreferrer">简道云 · 二手车商解决方案</a><a href="https://www.frazer.com/" target="_blank" rel="noopener noreferrer">Frazer · 车辆与经营管理</a><a href="https://www.che300.com/web_app_download/app_qrcode_major?city=12" target="_blank" rel="noopener noreferrer">车300 · 车源服务介绍</a><p style="margin-top:13px">参考核验：2026-10-25。当前未连接这些平台的数据接口，不提供实时市场估价或自动车况认证。</p></div></section></div></div>`;}
function field(label,name,type='text',value='',props={}){let attrs=Object.entries(props).filter(([k])=>k!=='full'&&k!=='hint').map(([k,v])=>v===true?k:v===false?'':`${k}="${esc(v)}"`).join(' ');return `<div class="field ${props.full?'full':''}"><label for="f-${name}">${esc(label)}${props.required?' *':''}</label>${type==='textarea'?`<textarea id="f-${name}" name="${name}" ${attrs}>${esc(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}>`}${props.hint?`<small>${esc(props.hint)}</small>`:''}</div>`;}
function selectField(label,name,options,value='',full=false){return `<div class="field ${full?'full':''}"><label for="f-${name}">${esc(label)}</label><select id="f-${name}" name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('')}</select></div>`;}
function showModal(title,sub,body,wide=false){const d=$('#dialog');if(d.open)d.close();d.style.width=wide?'780px':'650px';$('#dialog-body').innerHTML=`<button type="button" class="dialog-close" data-action="close" aria-label="关闭对话框">×</button><div class="dialog-heading"><div id="dialog-title">${esc(title)}</div><p>${esc(sub)}</p></div>${body}`;d.showModal();}
function formWrap(id,body,label='保存',extra=''){return `<form id="${id}" ${extra}><div class="form-grid">${body}</div><div class="form-actions">${btn('取消','close') }<button class="btn primary" type="submit">${esc(label)}</button></div></form>`;}
function carForm(id){const c=state.cars.find(c=>c.id===id)||{};editingPhotoSession++;photoBusy=0;modalPhotos=structuredClone(c.photos||[]);showModal(c.id?'编辑车辆档案':'拍照 · 车辆入库','先把车记下来，照片和费用可以随时补充。',formWrap('car-form',field('品牌与车型','name','text',c.name||'',{required:true,maxlength:80,placeholder:'例如：宝马 730Li'})+field('具体配置 / 车款','trim','text',c.trim||'',{maxlength:120,placeholder:'例如：2020款 豪华套装'})+field('首次上牌年份','year','number',c.year||new Date().getFullYear(),{required:true,min:1980,max:new Date().getFullYear()+1,step:1})+field('表显里程（万公里）','mileage','number',c.mileage??'',{required:true,min:0,max:999,step:.01})+field('收车价（元）','purchase','number',c.purchase??'',{required:true,min:0,max:1e9,step:.01})+field('挂牌价（元）','ask','number',c.ask??'',{required:true,min:0,max:1e9,step:.01})+field('入库日期','date','date',c.date||today(),{required:true,max:today()})+selectField('车辆状态','status',c.status==='已售'?['已售']:['在售','待检测','整备中','已预订'],c.status||'待检测')+selectField('车身颜色','color',['黑色','白色','灰色','银色','蓝色','绿色','红色','棕色','其他'],c.color||'黑色')+field('所在城市','city','text',c.city||'',{required:true,maxlength:40,placeholder:'例如：连云港'})+field('VIN / 车架号（选填）','vin','text',c.vin||'',{maxlength:17,pattern:'[A-HJ-NPR-Za-hj-npr-z0-9]{17}|',hint:'填写时应为17位字母或数字；暂不自动识别。'})+field('负责人','owner','text',c.owner||'本人',{maxlength:30})+selectField('车况资料状态','condition',['待核实','已附资料待复核','人工核验已记录'],c.condition||'待核实',true)+`<div class="field full"><label>车辆照片（最多12张，第一张为封面）</label><div class="upload-area">${ic('camera')}<strong>手机直接拍，或从相册选多张</strong><div>每张不超过 15 MB；保存时自动压缩图片</div><div class="upload-buttons"><label>拍一张<input type="file" accept="image/*" capture="environment" data-photos="camera" aria-label="拍照上传车辆"></label><label>从相册选择<input type="file" accept="image/*" multiple data-photos="album" aria-label="选择车辆照片"></label></div></div><div id="photo-status" class="photo-status" role="status"></div><div class="photo-grid" id="photo-preview"></div></div>`+field('车辆备注 / 车况记录','notes','textarea',c.notes||'',{full:true,maxlength:3000,placeholder:'检测报告、补漆、维保、钥匙数量、证件情况等。'}),'保存车辆',`data-id="${esc(c.id||'')}"`)+`<div class="notice" style="margin-top:17px">收车价仅登记成本，不自动生成付款流水。整备及其他实际费用可在车辆档案中追加。照片保存在本机，建议定期导出完整备份。</div>`,true);renderPhotoPreview();}
function renderPhotoPreview(){const el=$('#photo-preview');if(!el)return;el.innerHTML=modalPhotos.map((p,i)=>`<figure class="${i===0?'cover':''}"><img src="${esc(p.data)}" alt="车辆照片 ${i+1}" data-action="photo-cover" data-id="${i}" title="点击设为封面" tabindex="0" role="button" aria-label="将第${i+1}张照片设为封面"><figcaption><span class="${i===0?'cover-label':''}">${i===0?'封面':'点击设为封面'}</span><button type="button" data-action="photo-remove" data-id="${i}" aria-label="删除第${i+1}张照片">删除</button></figcaption></figure>`).join('');}
async function addPhotos(files){const session=editingPhotoSession;photoBusy++;const status=$('#photo-status');try{for(const f of files){if(session!==editingPhotoSession)return;if(modalPhotos.length>=12){toast('每台车最多保存12张照片');break;}if(!f.type.startsWith('image/')||f.size>15*1048576){toast('请选择15 MB以内的图片文件');continue;}status.textContent='正在处理照片，请稍候…';try{const data=await compressImage(f);if(session!==editingPhotoSession)return;modalPhotos.push({id:uid(),data,name:f.name.slice(0,120)});renderPhotoPreview();}catch{toast('此图片无法读取，请改用 JPEG、PNG 或 WebP 格式。');}}if(session===editingPhotoSession&&status.isConnected)status.textContent=`已准备 ${modalPhotos.length} 张照片，保存车辆后生效。`;}finally{if(session===editingPhotoSession)photoBusy--;}}
async function compressImage(f){return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(f);img.onload=()=>{try{const scale=Math.min(1,1600/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.8));}catch(e){reject(e);}finally{URL.revokeObjectURL(url);}};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('图片格式不支持'));};img.src=url;});}
function viewCar(id){const c=state.cars.find(c=>c.id===id);if(!c)return;showModal(c.name,c.trim||'车辆档案',`<div class="detail-photo" id="detail-main-photo">${c.photos.length?`<img src="${esc(c.photos[0].data)}" alt="${esc(c.name)}封面">`:carArt(c.art,c.name)}</div>${c.photos.length?`<div class="photo-grid">${c.photos.map((p,i)=>`<figure><img src="${esc(p.data)}" alt="车辆照片 ${i+1}" data-action="view-photo" data-id="${esc(c.id)}:${i}" role="button" tabindex="0" aria-label="查看第${i+1}张照片"></figure>`).join('')}</div>`:'<p class="mini muted">当前为车辆示意图。点击“编辑与照片”上传实车照片。</p>'}<div class="actions">${badge(c.status)}${badge(days(c.date,c.soldDate||today())+' 天'+(c.status==='已售'?'成交周期':'库龄'),'gray')}${badge(c.condition,'amber')}</div><dl class="detail-grid">${[['首次上牌',c.year+'年'],['表显里程',c.mileage+'万公里'],['颜色 / 城市',c.color+' / '+c.city],['挂牌价',money(c.ask)],['负责人',c.owner||'本人'],['入库日期',c.date],['车架号',c.vin||'尚未填写']].map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><h3>单车成本账</h3><div class="cost-list"><div><span>收车价</span><span>${money(c.purchase)}</span></div>${c.fees.map(f=>`<div><span>${esc(f.name)}</span><span>${money(f.amount)}</span></div>`).join('')}<div><span>车辆总成本</span><span>${money(carCost(c))}</span></div><div><span>${c.status==='已售'?'成交毛利':'挂牌预期毛利'}</span><span class="${(c.status==='已售'?gross(c):c.ask-carCost(c))<0?'negative':'positive'}">${money(c.status==='已售'?gross(c):c.ask-carCost(c))}</span></div></div><div class="notice" style="margin:17px 0">${esc(c.notes||'尚未填写车况备注。')}<br>车况资料状态仅为人工记录，未接入第三方检测认证。</div><div class="actions">${btn('编辑与照片','edit-car','primary','camera',c.id)}${btn('追加费用','add-cost','','plus',c.id)}${c.status!=='已售'?btn('登记成交','add-sale','','check',c.id):''}${btn('展示卡 / 文案','share-card','','file',c.id)}</div>`,true);}
function costForm(id){const c=state.cars.find(c=>c.id===id);showModal('追加车辆费用',c.name,formWrap('cost-form',field('费用项目','name','text','',{required:true,maxlength:80,placeholder:'例如：轮胎整备 / 物流 / 过户'})+field('实际金额（元）','amount','number','',{required:true,min:.01,max:1e8,step:.01})+`<div class="field full"><div class="notice">追加到车辆总成本，自动重算毛利。不自动视为已经付款，实际付款请在资金流水另记。</div></div>`,'保存费用',`data-id="${id}"`));}
function customerForm(id){const c=state.customers.find(c=>c.id===id)||{};showModal(c.id?'编辑客户':'新增客户','记录真实需求与下一次联系时间。',formWrap('customer-form',field('客户称呼','name','text',c.name||'',{required:true,maxlength:40})+field('联系电话（选填）','phone','tel',c.phone||'',{maxlength:30})+field('预算上限（元）','budget','number',c.budget||'',{min:0,max:1e9})+selectField('跟进阶段','stage',['初次沟通','高意向','已预约','洽谈中','已成交','暂缓'],c.stage||'初次沟通')+field('线索来源','source','text',c.source||'',{maxlength:60,placeholder:'到店 / 抖音 / 朋友介绍'})+field('负责人','owner','text',c.owner||'本人',{maxlength:30})+field('下次跟进日期','next','date',c.next||today())+field('意向车型与需求','want','text',c.want||'',{required:true,maxlength:300,full:true})+field('备注','notes','textarea',c.notes||'',{full:true,maxlength:3000}),'保存客户',`data-id="${esc(c.id||'')}"`));}
function viewCustomer(id){const c=state.customers.find(c=>c.id===id);showModal(c.name,c.want,`<div class="actions">${badge(c.stage)}${badge('预算 '+(c.budget?wan(c.budget)+'万元':'待确认'),'gray')}${c.phone?`<a class="btn small" href="tel:${esc(c.phone.replace(/[^\d+]/g,''))}">${ic('phone')}拨打电话</a>`:''}</div><p class="contact-note" style="margin-top:17px">${esc(c.notes||'暂无备注')}</p><h3 style="margin-top:20px">跟进记录</h3><div class="timeline">${(c.logs||[]).map(l=>`<div class="timeline-item">${esc(l.text)}<small>${esc(l.date)}</small></div>`).join('')||'<div class="mini muted" style="padding-bottom:20px">还没有跟进记录。</div>'}</div>${formWrap('follow-form',field('本次沟通内容','text','textarea','',{required:true,full:true,maxlength:3000})+selectField('更新跟进阶段','stage',['初次沟通','高意向','已预约','洽谈中','已成交','暂缓'],c.stage)+field('下次联系日期','next','date',c.next||dateShift(1)),'保存跟进',`data-id="${id}"`)}<div class="actions" style="margin-top:12px">${btn('编辑客户','edit-customer','small','',id)}${btn('为客户建立寻车单','customer-request','small','search',id)}</div>`);}
function requestForm(id,customerId){const r=state.requests.find(r=>r.id===id)||{},c=state.customers.find(c=>c.id===customerId);showModal(r.id?'编辑寻车需求':'新建寻车需求','先整理筛选条件；车况和车源有效性需另行核实。',formWrap('request-form',field('需求名称 / 客户','name','text',r.name||(c?c.name+'寻车':''),{required:true,maxlength:100,full:true,placeholder:'例如：宝马730 · 王先生'})+field('车型关键词','model','text',r.model||'',{required:true,maxlength:80,placeholder:'例如：宝马 730'})+field('预算上限（元）','budget','number',r.budget||c?.budget||'',{min:0,max:1e9,placeholder:'留空表示不限'})+field('最早上牌年份','minYear','number',r.minYear||'',{min:1980,max:new Date().getFullYear()+1,step:1})+field('里程上限（万公里）','maxMileage','number',r.maxMileage||'',{min:0,max:999,step:.01})+selectField('颜色偏好','color',['不限','黑色','白色','灰色','银色','蓝色','绿色','红色','棕色','其他'],r.color||'不限')+field('地区范围','region','text',r.region||'全国',{maxlength:60,hint:'可填全国、具体城市、江苏或江苏及周边（含沪浙皖鲁）。'})+field('车况要求','condition','text',r.condition||'无重大事故 / 水泡 / 火烧',{maxlength:300,full:true})+field('其他要求','notes','textarea',r.notes||'',{maxlength:3000,full:true,placeholder:'具体配置、过户次数、排放、保养、能否接受补漆等。'}),'保存需求',`data-id="${esc(r.id||'')}"`));}
function queryText(r){return [r.model,'二手车',r.minYear?r.minYear+'年以后':'',r.budget?Math.round(r.budget/10000)+'万以内':'',r.maxMileage?r.maxMileage+'万公里以内':'',r.color==='不限'?'':r.color,r.region==='全国'?'':r.region,r.condition].filter(Boolean).join(' ');}
function searchRequest(id){const r=state.requests.find(r=>r.id===id);const q=queryText(r);showModal('外部搜索入口',r.name,`<div class="notice amber">这里会打开搜索引擎查询公开网页，不是在本站调用车源接口。搜索条件未必被搜索引擎严格执行，结果时效、在售状态与车况需人工确认。</div><div class="contact-note">${esc(q)}</div><div class="source-option"><div><h3>搜索全网公开信息</h3><p>使用当前需求组合关键词</p></div><a class="btn small" target="_blank" rel="noopener noreferrer" href="https://www.bing.com/search?q=${encodeURIComponent(q)}">打开搜索 ${ic('external')}</a></div>${[['二手车之家','che168.com'],['懂车帝','dongchedi.com'],['瓜子二手车','guazi.com']].map(([n,site])=>`<div class="source-option"><div><h3>${n}相关公开网页</h3><p>搜索引擎限定来源，非平台官方接口</p></div><a class="btn small" target="_blank" rel="noopener noreferrer" href="https://www.bing.com/search?q=${encodeURIComponent(q+' site:'+site)}">打开搜索 ${ic('external')}</a></div>`).join('')}<div class="actions" style="margin-top:22px">${btn('复制寻车条件','copy-request','primary','copy',id)}${btn('收藏找到的车源','add-candidate','','plus')}</div>`);}
function candidateForm(){showModal('收藏外部车源','仅保存你找到的线索，不自动认定车况或在售状态。',formWrap('candidate-form',field('车源标题','title','text','',{required:true,maxlength:160,full:true})+field('原始车源链接','url','url','',{required:true,full:true,maxlength:2000,placeholder:'https://…'})+field('来源平台','source','text','',{required:true,maxlength:60})+field('卖家报价（元，选填）','price','number','',{min:0,max:1e9})+field('记录日期','date','date',today(),{required:true,max:today()})+field('车况、询价与联系记录','notes','textarea','',{full:true,maxlength:3000}),'保存车源'));
}
function taskForm(){showModal('新建待办','把下一步行动写具体一点。',formWrap('task-form',field('要做的事情','title','text','',{required:true,full:true,maxlength:200})+field('提醒日期','date','date',today(),{required:true})+selectField('事项分类','type',['门店事务','客户跟进','车辆整备','销售交付','收付款'],'门店事务'),'保存待办'));}
function jobForm(id){const j=state.jobs.find(j=>j.id===id)||{};if(!stock().length&&!j.id){toast('请先录入一台库存车辆');return;}showModal(j.id?'编辑整备工单':'新建整备工单','跟进工作进度；预算不会自动记入车辆成本。',formWrap('job-form',selectField('关联车辆','carId',state.cars.filter(c=>c.status!=='已售'||c.id===j.carId).map(c=>[c.id,c.name+' · '+c.id.slice(0,8)]),j.carId||stock()[0]?.id,true)+field('整备项目','title','text',j.title||'',{required:true,full:true,maxlength:200})+field('供应商 / 维修店','vendor','text',j.vendor||'',{maxlength:100})+field('预算金额（元）','amount','number',j.amount??0,{required:true,min:0,max:1e8,step:.01})+field('计划完成日期','date','date',j.date||today(),{required:true})+selectField('工单状态','status',['待安排','进行中','已完成'],j.status||'待安排')+field('工单备注','note','textarea',j.note||'',{maxlength:3000,full:true}),'保存工单',`data-id="${esc(j.id||'')}"`));}
function saleForm(id){if(!stock().length){toast('请先录入库存车辆');return;}showModal('登记车辆成交','保存后车辆移入成交档案，已收金额同步登记收入流水。',formWrap('sale-form',selectField('成交车辆','carId',stock().map(c=>[c.id,c.name+' · '+c.id.slice(0,8)]),id||stock()[0].id,true)+field('成交价（元）','sale','number','',{required:true,min:.01,max:1e9,step:.01})+field('累计已收款（元）','received','number',0,{required:true,min:0,max:1e9,step:.01})+field('成交日期','soldDate','date',today(),{required:true,max:today()})+field('买家称呼','buyer','text','',{required:true,maxlength:80})+selectField('交付进度','delivery',['待过户','待交车','已交付'],'待过户',true),'保存成交'));
}
function deliveryForm(id){const c=state.cars.find(c=>c.id===id);showModal('收款与交付',c.name,`<div class="inline-stats"><div><strong>${money(c.sale)}</strong><small>成交价</small></div><div><strong>${money(receivable(c))}</strong><small>尚待收款</small></div></div>`+formWrap('delivery-form',field('本次追加收款（元）','amount','number',0,{required:true,min:0,max:receivable(c),step:.01})+field('收款日期','date','date',today(),{required:true,min:c.soldDate,max:today()})+selectField('交付进度','delivery',['待过户','待交车','已交付'],c.delivery||'待过户',true),'保存收款与进度',`data-id="${id}"`));}
function ledgerForm(){showModal('记一笔收支','按实际发生金额登记；售车收款请优先在销售交付中登记。',formWrap('ledger-form',selectField('收支方向','type',['支出','收入'],'支出')+selectField('收支项目','category',['收车付款','整备付款','物流过户','门店运营','佣金及服务','其他'],'其他')+field('金额（元）','amount','number','',{required:true,min:.01,max:1e9,step:.01})+field('发生日期','date','date',today(),{required:true,max:today()})+selectField('关联车辆（选填）','carId',[['','不关联车辆'],...state.cars.map(c=>[c.id,c.name+' · '+c.id.slice(0,8)])],'',true)+field('备注','note','textarea','',{maxlength:2000,full:true}),'保存流水'));
}
function vehicleCopy(c){return `【方驰车业】\n${c.name} ${c.trim}\n首次上牌：${c.year}年\n表显里程：${c.mileage}万公里\n车辆颜色：${c.color}\n所在地：${c.city}\n挂牌价：${wan(c.ask)}万元\n车况资料状态：${c.condition}\n具体车况、配置与在售情况请联系门店核实，实车与检测资料为准。`;}
function shareCard(id){const c=state.cars.find(c=>c.id===id);showModal('车辆展示卡','个人版预览；尚未发布到网上。',`<div class="notice">展示卡只包含对外车辆信息，不包含收车价、成本和利润。此版支持复制文案、下载图片或打印；公开展厅将在第二版接入。</div><div class="print-card"><div class="mini muted" style="margin-bottom:10px">方驰车业</div><div class="detail-photo">${c.photos.length?`<img src="${esc(c.photos[0].data)}" alt="车辆封面">`:carArt(c.art,c.name)}</div><h3>${esc(c.name)}</h3><p class="mini muted">${esc(c.trim)}</p><p>${c.year}年 · ${c.mileage}万公里 · ${esc(c.color)} · ${esc(c.city)}</p><div class="price">${wan(c.ask)}<small>万元</small></div><p class="mini muted" style="margin-top:12px">车况与在售情况请联系门店核实，以实车及检测资料为准。</p></div><div class="actions" style="margin-top:20px">${btn('复制车辆文案','copy-car','primary','copy',id)}${btn('下载展示图片','download-card','','download',id)}${btn('打印展示卡','print','','file')}</div>`);}
async function copyText(t){try{await navigator.clipboard.writeText(t);toast('已复制');}catch{showModal('复制内容','当前浏览器未允许自动复制，可长按或全选复制。',`<textarea readonly style="width:100%;min-height:240px;padding:12px">${esc(t)}</textarea>`);}}
async function downloadCard(id){const c=state.cars.find(c=>c.id===id);const can=document.createElement('canvas');can.width=1080;can.height=1350;const x=can.getContext('2d');x.fillStyle='#f2f6f1';x.fillRect(0,0,1080,1350);x.fillStyle='#173c3c';x.fillRect(0,0,1080,140);x.fillStyle='#fff';x.font='600 45px "PingFang SC",sans-serif';x.fillText('方驰车业',65,90);x.fillStyle='#e0e9df';x.fillRect(55,185,970,580);if(c.photos.length){try{const img=await new Promise((res,rej)=>{const i=new Image();i.onload=()=>res(i);i.onerror=rej;i.src=c.photos[0].data;});const k=Math.min(970/img.width,580/img.height);x.drawImage(img,55+(970-img.width*k)/2,185+(580-img.height*k)/2,img.width*k,img.height*k);}catch{toast('封面图片无法读取');return;}}else{x.fillStyle='#789286';x.font='32px "PingFang SC",sans-serif';x.fillText('实车照片待补充',400,490);}x.fillStyle='#213e32';x.font='600 52px "PingFang SC",sans-serif';x.fillText(c.name.slice(0,22),65,865);x.font='28px "PingFang SC",sans-serif';x.fillStyle='#7b8b7c';x.fillText(c.trim.slice(0,35),65,922);x.font='32px "PingFang SC",sans-serif';x.fillText(`${c.year}年 · ${c.mileage}万公里 · ${c.color} · ${c.city}`.slice(0,40),65,992);x.font='600 76px "Avenir Next",sans-serif';x.fillStyle='#22745f';x.fillText(wan(c.ask)+' 万元',65,1122);x.font='24px "PingFang SC",sans-serif';x.fillStyle='#7b8b7c';x.fillText('车况与在售情况请联系门店核实，以实车及检测资料为准。',65,1230);can.toBlob(blob=>{downloadBlob(blob,`方驰车业-${c.name}-展示卡.png`);toast('展示卡已生成，请查看下载文件');},'image/png');}
function safeURL(url){try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?u.href:'#';}catch{return '#';}}
function downloadBlob(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function backup(){downloadBlob(new Blob([JSON.stringify({format:'fangchi-backup-v1',exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),`方驰车业-完整备份-${today()}.json`);toast('已生成完整备份，包含车辆照片；请妥善保管。');}
function csv(rows,name){const cell=v=>'"'+String(v??'').replace(/^[=+\-@\t\r]/,"'$&").replace(/"/g,'""')+'"';downloadBlob(new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),name);}
function install(){showModal('把方驰车业放到主屏幕','公开版工作台，随手就能打开。',`<img class="install-icon" src="./icon-192.png" alt="方驰车业应用图标"><div class="timeline"><div class="timeline-item">iPhone / iPad<small>用 Safari 打开网站，点分享菜单，选择“添加到主屏幕”。若有“作为网页 App 打开”，请启用。</small></div><div class="timeline-item">安卓手机<small>用支持安装的浏览器打开，点菜单中的“安装应用”或“添加到主屏幕”。</small></div><div class="timeline-item">Mac / Windows<small>Chrome、Edge 可使用地址栏安装按钮；支持的 Safari 可用“添加到程序坞”。</small></div></div><div class="notice amber">安装与跨设备同步是两件事。当前数据保存在当前浏览器；安装后的应用可能使用独立存储。请先导出完整备份，首次在应用中打开后可导入恢复。公开版可直接访问，无需账号登录。</div>${deferredInstall?btn('安装方驰车业','install-now','primary','download'):''}<div class="sources" style="margin-top:15px"><a href="https://support.apple.com/zh-cn/guide/iphone/iphea86e5236/ios" target="_blank" rel="noopener noreferrer">Apple：将网站变成 App</a></div>`);}
const textVal=(fd,k)=>String(fd.get(k)||'').trim();
const numVal=(fd,k)=>Math.round(Number(fd.get(k)||0)*100)/100;
function checkDate(s){return /^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(Date.parse(s+'T12:00:00Z'))&&new Date(s+'T12:00:00Z').toISOString().slice(0,10)===s;}
async function onSubmit(e){e.preventDefault();const f=e.target;if(!(f instanceof HTMLFormElement))return;const fd=new FormData(f);if(f.id==='global-search'){page='inventory';location.hash='inventory';query=textVal(fd,'query');stockFilter='全部';render();return;}
 if(!f.reportValidity())return;let ok=false;const button=f.querySelector('[type="submit"]');if(button)button.disabled=true;
 try{
 if(f.id==='car-form'){
  if(photoBusy){toast('照片仍在处理，请稍候再保存');return;}const id=f.dataset.id,old=state.cars.find(c=>c.id===id),vin=textVal(fd,'vin').toUpperCase();if(vin&&state.cars.some(c=>c.vin===vin&&c.id!==id)){toast('此VIN已存在，请核对车辆档案');return;}
  const record={...(old||{id:uid(),fees:[],art:'#657e71'}),name:textVal(fd,'name'),trim:textVal(fd,'trim'),year:numVal(fd,'year'),mileage:numVal(fd,'mileage'),purchase:numVal(fd,'purchase'),ask:numVal(fd,'ask'),date:textVal(fd,'date'),status:textVal(fd,'status'),color:textVal(fd,'color'),city:textVal(fd,'city'),vin,owner:textVal(fd,'owner'),condition:textVal(fd,'condition'),notes:textVal(fd,'notes'),photos:structuredClone(modalPhotos)};
  if(!checkDate(record.date)||record.date>today()||(old?.soldDate&&record.date>old.soldDate)){toast('入库日期须有效，且不能晚于今天或成交日期');return;}if(!record.name||!record.city){toast('请填写车型和所在城市');return;}
  ok=await commit(()=>{if(old)state.cars[state.cars.indexOf(old)]=record;else state.cars.unshift(record);},'车辆档案已保存，照片一起留存在本机');
 }else if(f.id==='cost-form'){const c=state.cars.find(c=>c.id===f.dataset.id);ok=await commit(()=>c.fees.push({name:textVal(fd,'name'),amount:numVal(fd,'amount')}),'费用已计入车辆成本');
 }else if(f.id==='customer-form'){const old=state.customers.find(c=>c.id===f.dataset.id),record={...(old||{id:uid(),logs:[]}),name:textVal(fd,'name'),phone:textVal(fd,'phone'),want:textVal(fd,'want'),budget:numVal(fd,'budget'),stage:textVal(fd,'stage'),source:textVal(fd,'source'),owner:textVal(fd,'owner'),next:textVal(fd,'next'),notes:textVal(fd,'notes')};if(!record.name||!record.want){toast('请填写客户称呼和意向需求');return;}ok=await commit(()=>{if(old)state.customers[state.customers.indexOf(old)]=record;else state.customers.unshift(record);});
 }else if(f.id==='follow-form'){const c=state.customers.find(c=>c.id===f.dataset.id);ok=await commit(()=>{c.logs.unshift({date:today(),text:textVal(fd,'text')});c.stage=textVal(fd,'stage');c.next=textVal(fd,'next');},'已记录本次跟进');
 }else if(f.id==='request-form'){const old=state.requests.find(r=>r.id===f.dataset.id),r={id:old?.id||uid(),created:old?.created||today(),name:textVal(fd,'name'),model:textVal(fd,'model'),budget:numVal(fd,'budget'),minYear:numVal(fd,'minYear'),maxMileage:numVal(fd,'maxMileage'),color:textVal(fd,'color'),region:textVal(fd,'region'),condition:textVal(fd,'condition'),notes:textVal(fd,'notes')};if(!r.name||!r.model){toast('请填写需求名称和车型关键词');return;}ok=await commit(()=>{if(old)state.requests[state.requests.indexOf(old)]=r;else state.requests.unshift(r);selectedMatch=r.id;},'寻车需求已保存');
 }else if(f.id==='candidate-form'){const url=textVal(fd,'url');if(safeURL(url)==='#'){toast('请输入 http 或 https 开头的原始车源链接');return;}ok=await commit(()=>state.candidates.unshift({id:uid(),title:textVal(fd,'title'),url,source:textVal(fd,'source'),price:numVal(fd,'price'),date:textVal(fd,'date'),notes:textVal(fd,'notes')}),'已收藏车源，车况与在售状态待核实');
 }else if(f.id==='task-form'){ok=await commit(()=>state.tasks.unshift({id:uid(),title:textVal(fd,'title'),date:textVal(fd,'date'),type:textVal(fd,'type'),done:false}));
 }else if(f.id==='job-form'){const old=state.jobs.find(j=>j.id===f.dataset.id),j={id:old?.id||uid(),carId:textVal(fd,'carId'),title:textVal(fd,'title'),vendor:textVal(fd,'vendor'),amount:numVal(fd,'amount'),date:textVal(fd,'date'),status:textVal(fd,'status'),note:textVal(fd,'note')};ok=await commit(()=>{if(old)state.jobs[state.jobs.indexOf(old)]=j;else state.jobs.unshift(j);});
 }else if(f.id==='sale-form'){const c=state.cars.find(c=>c.id===textVal(fd,'carId'));if(!c||c.status==='已售'){toast('此车辆已不在库存，请重新选择');return;}const sale=numVal(fd,'sale'),received=numVal(fd,'received'),soldDate=textVal(fd,'soldDate');if(received>sale){toast('已收款不能超过成交价');return;}if(!checkDate(soldDate)||soldDate<c.date||soldDate>today()){toast('成交日期不能早于入库日期或晚于今天');return;}ok=await commit(()=>{Object.assign(c,{status:'已售',sale,received,soldDate,buyer:textVal(fd,'buyer'),delivery:textVal(fd,'delivery')});if(received>0)state.ledger.unshift({id:uid(),date:soldDate,type:'收入',category:'售车收款',amount:received,carId:c.id,note:c.buyer+' · 成交时收款',locked:true});},'成交已登记，已收车款同步记入流水');
 }else if(f.id==='delivery-form'){const c=state.cars.find(c=>c.id===f.dataset.id),amount=numVal(fd,'amount');if(amount>receivable(c)){toast('追加收款不能超过剩余车款');return;}ok=await commit(()=>{c.received+=amount;c.delivery=textVal(fd,'delivery');if(amount>0)state.ledger.unshift({id:uid(),date:textVal(fd,'date'),type:'收入',category:'售车收款',amount,carId:c.id,note:(c.buyer||'客户')+' · 追加收款',locked:true});},'收款与交付进度已保存');
 }else if(f.id==='ledger-form'){ok=await commit(()=>state.ledger.unshift({id:uid(),date:textVal(fd,'date'),type:textVal(fd,'type'),category:textVal(fd,'category'),amount:numVal(fd,'amount'),carId:textVal(fd,'carId'),note:textVal(fd,'note')}));
 }else if(f.id==='settings-form'){ok=await commit(()=>{state.settings.target=numVal(fd,'target');},'月度销售目标已更新');return;}
 if(ok)$('#dialog').close();
 }catch{toast('此操作未完成，请检查输入后重试。');}finally{if(button?.isConnected)button.disabled=false;}
}
async function handleAction(action,id,el){
 if(action==='go')go(id);else if(action==='menu')$('#sidebar').classList.toggle('open');else if(action==='close')$('#dialog').close();
 else if(action==='add-car')carForm();else if(action==='edit-car')carForm(id);else if(action==='view-car')viewCar(id);else if(action==='add-cost')costForm(id);
 else if(action==='photo-cover'){const i=Number(id);if(modalPhotos[i])modalPhotos.unshift(modalPhotos.splice(i,1)[0]);renderPhotoPreview();}
 else if(action==='photo-remove'){modalPhotos.splice(Number(id),1);renderPhotoPreview();}
 else if(action==='view-photo'){const parts=id.split(':'),c=state.cars.find(c=>c.id===parts[0]),p=c?.photos[Number(parts[1])];if(p)$('#detail-main-photo').innerHTML=`<img src="${esc(p.data)}" alt="${esc(c.name)}实车照片">`;}
 else if(action==='stock-filter'){stockFilter=id;render();}else if(action==='toggle-view'){stockView=stockView==='list'?'cards':'list';render();}
 else if(action==='aged-stock'){page='inventory';stockFilter='长库龄';query='';location.hash=page;render();window.scrollTo(0,0);}
 else if(action==='add-customer')customerForm();else if(action==='edit-customer')customerForm(id);else if(action==='view-customer')viewCustomer(id);else if(action==='customer-filter'){customerFilter=id;render();}
 else if(action==='customer-request')requestForm(null,id);else if(action==='add-request')requestForm();else if(action==='edit-request')requestForm(id);else if(action==='match-request'){selectedMatch=id;render();toast('已更新下方库存初筛结果');}
 else if(action==='search-request')searchRequest(id);else if(action==='copy-request'){const r=state.requests.find(r=>r.id===id);if(r)await copyText(queryText(r));}
 else if(action==='add-candidate')candidateForm();else if(action==='delete-request'){if(confirm('删除这条寻车需求？'))await commit(()=>state.requests=state.requests.filter(r=>r.id!==id),'寻车需求已删除');}
 else if(action==='delete-candidate'){if(confirm('删除这条外部车源记录？'))await commit(()=>state.candidates=state.candidates.filter(c=>c.id!==id),'车源记录已删除');}
 else if(action==='add-task')taskForm();else if(action==='toggle-task')await commit(()=>{const t=state.tasks.find(t=>t.id===id);if(t)t.done=!t.done;},'待办状态已更新');
 else if(action==='add-job')jobForm();else if(action==='edit-job')jobForm(id);else if(action==='advance-job')await commit(()=>{const j=state.jobs.find(j=>j.id===id);j.status=j.status==='待安排'?'进行中':'已完成';},'工单进度已更新；实际费用请在车辆档案登记');
 else if(action==='add-sale')saleForm(id);else if(action==='delivery')deliveryForm(id);else if(action==='add-ledger')ledgerForm();
 else if(action==='delete-ledger'){const l=state.ledger.find(l=>l.id===id);if(l?.locked){toast('关联成交的收款不能直接删除');return;}if(confirm('删除这条收支流水？'))await commit(()=>state.ledger=state.ledger.filter(l=>l.id!==id),'流水已删除');}
 else if(action==='share-card')shareCard(id);else if(action==='copy-car'){const c=state.cars.find(c=>c.id===id);if(c)await copyText(vehicleCopy(c));}else if(action==='download-card')await downloadCard(id);
 else if(action==='backup')backup();else if(action==='restore')$('#restore-file').click();
 else if(action==='export-cars')csv([['编号','车型','配置','年份','里程（万公里）','状态','入库日期','城市','颜色','收车价（元）','车辆费用（元）','总成本（元）','挂牌价（元）','库龄（天）','VIN','备注'],...stock().map(c=>[c.id,c.name,c.trim,c.year,c.mileage,c.status,c.date,c.city,c.color,c.purchase,sum(c.fees,f=>f.amount),carCost(c),c.ask,days(c.date),c.vin,c.notes])],`方驰车业-库存-${today()}.csv`);
 else if(action==='export-ledger')csv([['日期','收支方向','项目','金额（元）','关联车辆','备注'],...state.ledger.map(l=>[l.date,l.type,l.category,l.amount,state.cars.find(c=>c.id===l.carId)?.name||'',l.note])],`方驰车业-收支流水-${today()}.csv`);
 else if(action==='start-empty'||action==='load-demo')showModal(action==='start-empty'?'建立空白个人台账':'载入演示台账','此操作会替换当前浏览器中的全部台账和照片。',`<div class="notice amber">请先导出完整备份。确认后，现有车辆、照片、客户和经营记录将从当前台账清除，无法在网站内撤销。</div><div class="actions">${btn('先导出备份','backup','','download')}${btn('取消','close')}${btn(action==='start-empty'?'确认建立空白台账':'确认载入演示',action==='start-empty'?'confirm-empty':'confirm-demo','danger')}</div>`);
 else if(action==='confirm-empty'||action==='confirm-demo'){const replacement=seed();if(action==='confirm-empty'){for(const k of ['cars','customers','requests','candidates','jobs','tasks','ledger'])replacement[k]=[];replacement.demo=false;replacement.settings=structuredClone(state.settings);}const ok=await commit(()=>state=replacement,action==='confirm-empty'?'空白个人台账已建立':'演示数据已载入');if(ok){selectedMatch='';$('#dialog').close();}}
 else if(action==='install')install();else if(action==='install-now'){if(deferredInstall){await deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;$('#dialog').close();}}
 else if(action==='submit-settings')$('#settings-form').requestSubmit();else if(action==='print')window.print();
}
function validateBackup(obj){
 const s=obj?.format==='fangchi-backup-v1'?obj.state:null;if(!s||s.version!==1||typeof s.demo!=='boolean'||!s.settings||s.settings.storeName!=='方驰车业'||!Number.isInteger(s.settings.target)||s.settings.target<1||s.settings.target>10000)throw Error('不是可识别的方驰车业备份');
 const validString=(v,max=5000)=>typeof v==='string'&&v.length<=max,validN=(v,min=0,max=1e10)=>typeof v==='number'&&Number.isFinite(v)&&v>=min&&v<=max;
 const keys=['cars','customers','requests','candidates','jobs','tasks','ledger'];for(const key of keys){if(!Array.isArray(s[key])||s[key].length>20000)throw Error('备份记录结构不完整');const ids=new Set();for(const r of s[key]){if(!r||!validString(r.id,100)||!r.id||ids.has(r.id))throw Error('记录编号缺失或重复');ids.add(r.id);for(const [k,v]of Object.entries(r)){if(['__proto__','constructor','prototype'].includes(k))throw Error('无效字段');if(typeof v==='string'&&!validString(v,6000))throw Error('文本字段过长');}}}
 for(const c of s.cars){if(!['在售','待检测','整备中','已预订','已售'].includes(c.status)||!Number.isInteger(c.year)||c.year<1980||c.year>new Date().getFullYear()+1||!['name','trim','color','city','vin','owner','notes','condition'].every(k=>validString(c[k]))||!c.name||!checkDate(c.date)||c.date>today()||!validN(c.mileage,0,999)||!validN(c.purchase)||!validN(c.ask)||!/^#[0-9a-f]{6}$/i.test(c.art)||!Array.isArray(c.photos)||c.photos.length>12||!Array.isArray(c.fees)||c.fees.length>2000)throw Error('车辆数据不完整');for(const f of c.fees)if(!validString(f.name,80)||!validN(f.amount))throw Error('车辆费用无效');for(const p of c.photos)if(!validString(p.data,8e6)||!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(p.data)||!validString(p.id,100)||!validString(p.name,120))throw Error('照片数据无效');if(c.status==='已售'&&(!validN(c.sale,.01)||!validN(c.received,0,c.sale)||!checkDate(c.soldDate)||c.soldDate<c.date||c.soldDate>today()||!['待过户','待交车','已交付'].includes(c.delivery)||!validString(c.buyer,80)))throw Error('成交数据无效');}
 for(const c of s.customers){if(!['name','phone','want','source','owner','notes'].every(k=>validString(c[k]))||!validN(c.budget)||!['初次沟通','高意向','已预约','洽谈中','已成交','暂缓'].includes(c.stage)||(c.next&&!checkDate(c.next))||!Array.isArray(c.logs)||c.logs.length>20000||c.logs.some(l=>!checkDate(l.date)||!validString(l.text)))throw Error('客户数据无效');}
 for(const r of s.requests)if(!['name','model','color','region','condition','notes'].every(k=>validString(r[k]))||!validN(r.budget)||!validN(r.minYear,0,2200)||!validN(r.maxMileage,0,999)||!checkDate(r.created))throw Error('寻车需求数据无效');
 for(const c of s.candidates)if(!validString(c.title)||!validString(c.source)||!validString(c.notes)||!validN(c.price)||!checkDate(c.date)||safeURL(c.url)==='#')throw Error('外部车源数据无效');
 for(const j of s.jobs)if(!s.cars.some(c=>c.id===j.carId)||!['title','vendor','note'].every(k=>validString(j[k]))||!checkDate(j.date)||!validN(j.amount)||!['待安排','进行中','已完成'].includes(j.status))throw Error('整备工单数据无效');
 for(const t of s.tasks)if(!validString(t.title)||!validString(t.type)||!checkDate(t.date)||typeof t.done!=='boolean')throw Error('待办数据无效');
 for(const l of s.ledger)if(!checkDate(l.date)||!['收入','支出'].includes(l.type)||!validN(l.amount,.01)||!['category','note','carId'].every(k=>validString(l[k]))||(l.carId&&!s.cars.some(c=>c.id===l.carId)))throw Error('收支数据无效');
 return s;
}
document.addEventListener('submit',onSubmit);
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){handleAction(el.dataset.action,el.dataset.id||'',el).catch(()=>toast('操作未完成，请重试。'));return;}if($('#sidebar').classList.contains('open')&&!e.target.closest('#sidebar'))$('#sidebar').classList.remove('open');});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('img[data-action]')){e.preventDefault();e.target.click();}});
document.addEventListener('input',e=>{if(e.target.id==='inventory-query'){const start=e.target.selectionStart;query=e.target.value;const y=scrollY;render();const input=$('#inventory-query');input.focus();input.setSelectionRange(start,start);window.scrollTo(0,y);}});
document.addEventListener('change',async e=>{if(e.target.matches('[data-photos]'))await addPhotos([...e.target.files]);if(e.target.id==='restore-file'){const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>200*1048576){toast('备份超过200 MB，请使用较小的备份文件');return;}try{const restored=validateBackup(JSON.parse(await f.text()));showModal('恢复备份','将替换当前浏览器台账，请确认备份内容。',`<div class="notice">备份包含 ${restored.cars.length} 台车辆、${sum(restored.cars,c=>c.photos.length)} 张照片、${restored.customers.length} 位客户。${restored.demo?'此文件为演示台账。':'此文件为个人台账。'}</div><div class="actions">${btn('先备份当前台账','backup','','download')}${btn('取消','close')}<button type="button" class="btn danger" id="confirm-restore">确认替换并恢复</button></div>`);$('#confirm-restore').onclick=async()=>{const ok=await commit(()=>state=restored,'备份已恢复到当前浏览器');if(ok){selectedMatch='';$('#dialog').close();}};}catch(error){toast('无法导入：'+error.message);}}});
$('#dialog').addEventListener('close',()=>{if(!$('#dialog').open){editingPhotoSession++;modalPhotos=[];photoBusy=0;}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(pages[p]&&p!==page){page=p;query='';render();window.scrollTo(0,0);}});
window.addEventListener('offline',()=>toast('网络已断开，当前台账仍可在本机操作。'));
(async()=>{try{await initDB();page=pages[location.hash.slice(1)]?location.hash.slice(1):'overview';render();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch{$('#main').innerHTML=`<div class="empty"><h1>浏览器暂时无法保存台账</h1><p>请使用普通浏览模式，并允许此网站使用本地存储，然后刷新页面。</p><p>建议使用 Safari、Chrome 或 Edge 的最新版本。</p></div>`;}})();
